style.css:
/* Define general page structure */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: Arial, sans-serif;
  background-color: #3E1E8C; /* Dark Purple Background Color */
  color: white; /* Default text color */
  line-height: 1.5;
  background-size: cover;
  background-position: center;
  /* Uncomment and update the path below if you want to use a custom background image */
  /* background-image: url('path-to-your-background-image.jpg'); */
}

/* Header section */
header {
  background-color: rgba(0, 0, 0, 0.6); /* Dark semi-transparent overlay */
  padding: 20px;
  text-align: center;
}

header h1 {
  color: #fff;
  font-size: 36px;
}

/* Main Content */
main {
  padding: 20px;
}

h2 {
  font-size: 24px;
  color: #fff;
}

section {
  background-color: rgba(0, 0, 0, 0.5); /* Dark transparent background for video sections */
  margin: 20px 0;
  padding: 20px;
}
